def build_program(d4,palette):
    source="from collections import Counter\nBG=__BG__\nMARK=__MARK__\nCOLOURS=__COLOURS__\nMECHANISMS=('plain','repeated_nonmarker')\n\ndef _layouts(g):\n H,W=len(g),len(g[0]);layouts=[]\n for horizontal in (True,False):\n  N,M=(H,W) if horizontal else (W,H)\n  at=lambda r,c:g[r][c] if horizontal else g[c][r]\n  for edge in (0,N-1):\n   cells=[c for c in range(M) if at(edge,c)!=BG]\n   if len(cells)!=1 or at(edge,cells[0])!=MARK:continue\n   mc=cells[0];bars=[];side=None;good=True\n   for r in range(N):\n    if r==edge:continue\n    cs=[c for c in range(M) if at(r,c)!=BG]\n    if not cs:continue\n    if len(cs) not in (2,3,4,5) or cs!=list(range(min(cs),max(cs)+1)) or len({at(r,c) for c in cs})!=1:\n     good=False;break\n    sg=-1 if max(cs)<mc else 1 if min(cs)>mc else 0\n    if not sg or (side is not None and side!=sg):good=False;break\n    side=sg;bars.append((r,len(cs),at(r,cs[0])))\n   if not good or not bars:continue\n   distances=sorted(abs(r-edge) for r,_,_ in bars)\n   if distances[0] not in (1,2) or distances!=list(range(distances[0],N,2)):continue\n   layouts.append((horizontal,mc,bars))\n return layouts\n\ndef _outputs(g,mechanism):\n answers=[]\n for horizontal,mc,bars in _layouts(g):\n  if mechanism=='plain':baselines=[None]\n  else:\n   counts=Counter(L for _,L,c in bars if c!=MARK)\n   baselines=[L for L,n in counts.items() if n>1] or [None]\n  for base in baselines:\n   out=[r[:] for r in g]\n   for r,L,_ in bars:\n    n=L-1 if base is None or base==L else L-base\n    colour=COLOURS[(n*n)%10]\n    if horizontal:out[r][mc]=colour\n    else:out[mc][r]=colour\n   answers.append(out)\n return answers\n\ndef solve(demonstrations,grid):\n mechanisms=list(MECHANISMS)\n for d in demonstrations or []:\n  a,b=(d['input'],d['output']) if isinstance(d,dict) else d\n  mechanisms=[m for m in mechanisms if b in _outputs(a,m)]\n  if not mechanisms:return None\n outs=[o for m in mechanisms for o in _outputs(grid,m)]\n if not outs or any(o!=outs[0] for o in outs):return None\n return outs[0]\n"
    return source.replace('__BG__',str(palette[0])).replace('__MARK__',str(palette[5])).replace('__COLOURS__',repr(list(palette)))
